50	struct NameRecord
51	{
52	  hb_language_t language (hb_face_t *face) const
53	  {
54	    unsigned int p = platformID;
55	    unsigned int l = languageID;
56	
57	    if (p == 3)
58	      return _hb_ot_name_language_for_ms_code (l);
