71	  uint16_t score () const
72	  {
73	    /* Same order as in cmap::find_best_subtable(). */
74	    unsigned int p = platformID;
75	    unsigned int e = encodingID;
76	
77	    /* 32-bit. */
78	    if (p == 3 && e == 10) return 0;
79	    if (p == 0 && e ==  6) return 1;
80	    if (p == 0 && e ==  4) return 2;
81	
82	    /* 16-bit. */
83	    if (p == 3 && e ==  1) return 3;
84	    if (p == 0 && e ==  3) return 4;
85	    if (p == 0 && e ==  2) return 5;
86	    if (p == 0 && e ==  1) return 6;
87	    if (p == 0 && e ==  0) return 7;
88	
89	    /* Symbol. */
90	    if (p == 3 && e ==  0) return 8;
91	
92	    /* We treat all Mac Latin names as ASCII only. */
93	    if (p == 1 && e ==  0) return 10; /* 10 is magic number :| */
94	
95	    return UNSUPPORTED;
96	  }
