126	static int
127	_hb_ot_name_entry_cmp_key (const void *pa, const void *pb)
128	{
129	  const hb_ot_name_entry_t *a = (const hb_ot_name_entry_t *) pa;
130	  const hb_ot_name_entry_t *b = (const hb_ot_name_entry_t *) pb;
131	
132	  /* Compare by name_id, then language. */
133	
134	  if (a->name_id != b->name_id)
135	    return a->name_id < b->name_id ? -1 : +1;
136	
137	  if (a->language == b->language) return 0;
138	  if (!a->language) return -1;
139	  if (!b->language) return +1;
140	  return strcmp (hb_language_to_string (a->language),
141			 hb_language_to_string (b->language));
142	}
