227	  bool sanitize (hb_sanitize_context_t *c) const
228	  {
229	    TRACE_SANITIZE (this);
230	    return_trace (c->check_struct (this) &&
231			  likely (format == 0 || format == 1) &&
232			  c->check_array (nameRecordZ.arrayZ, count) &&
233			  c->check_range (this, stringOffset));
